void Solver::bump_var(int var, double coeff) {
    if (coeff <= 0.0) return;                 // ignore non‑positive coefficients

    double inc = var_inc * coeff;
    double &act = activity[var];
    act += inc;                               // update activity

    // overflow protection: rescale all activities if limit exceeded
    if (act > 1e100) {
        const double SCALE = 1e-100;
        for (int i = 1; i <= vars; ++i) activity[i] *= SCALE;
        var_inc *= SCALE;
    }

    // keep VSIDS heap consistent
    if (vsids.inHeap(var)) vsids.update(var);
}
